   <div id="root"></div>

   <script>
     const notificationOptions = [
       "Email",
       "SMS",
       "Push Notifications"
     ];

     function RadioOption({ id, name, value, label }) {
       return `
         <label class="radio-card" for="${id}">
           <input id="${id}" type="radio" name="${name}" value="${value}" required>
           <span class="radio-text">${label}</span>
         </label>
       `;
     }

     function FormField({ question, name, options }) {
       const optionMarkup = options
         .map((option, index) => RadioOption({
           id: `${name}-${index}`,
           name,
           value: option,
           label: option
         }))
         .join("");

       return `
         <div class="form-field">
           <div class="form-label">${question}</div>
           <div class="radio-list" role="radiogroup" aria-label="${question}">
             ${optionMarkup}
           </div>
         </div>
       `;
     }

     function SubmitButton({ label }) {
       return `<button class="submit-button" type="submit">${label}</button>`;
     }

