               question: "How do you prefer to receive notifications?",
               name: "notificationPreference",
               options: notificationOptions
             })}
             ${SubmitButton({ label: "Submit" })}
           </form>
         </main>
       `;
     }

     document.getElementById("root").innerHTML = App();
   </script>
